/* C evaluation fixture for the bounded polyhedral optimizer. */
long kernel(long seed){double a[576],b[576],c[576];for(long i=0;i<24;i++)for(long j=0;j<24;j++){a[i*24+j]=(i+j+seed)&15;b[i*24+j]=(i*3+j)&7;c[i*24+j]=0;}for(long i=0;i<24;i++)for(long j=0;j<24;j++)for(long k=0;k<24;k++)c[i*24+j]+=a[i*24+k]*b[j*24+k];long sum=0;for(long i=0;i<24;i++)for(long j=0;j<24;j++)sum+=(long)c[i*24+j]*(i+j+1);return sum;}
